REPLACE INTO `page_content` VALUES (8,'about_intro',NULL,'The Eswatini Standards Authority (ESWASA) is the national body mandated to develop, promote, and enforce standards and quality assurance in Eswatini.','2026-03-29 11:49:52');
REPLACE INTO `page_content` VALUES (9,'about_vision',NULL,'A competitive and Sustainable Trade Environment informed by effective standardization and conformity assurance in Eswatini.','2026-03-29 11:49:52');
REPLACE INTO `page_content` VALUES (10,'about_mission',NULL,'We provide and promote internationally recognized quality standards and conformity assessment services to improve business performance, minimize health and safety risks and ensure environmental integrity in collaboration with regulators.','2026-03-29 11:49:52');
REPLACE INTO `page_content` VALUES (11,'about_history',NULL,'The Eswatini Standards Authority (ESWASA) is a government parastatal organisation within the Ministry of Commerce, Industry, and Trade (MCIT) that was established under the Standards and Quality Act (10) 2003, amended in 2023. \r\n\r\nESWASA, being the National Standards Body of Eswatini, is mandated by this Act to advance quality and standards in local businesses, government, and industry.\r\n\r\nESWASA is mandated to promote quality and standards in local businesses, government, and industry. It also empowers the Authority to be the sole custodian of all issues relating to standards and quality in Eswatini.\r\n\r\nThe decision to establish ESWASA was in line with regional and international trends initiated by World Trade Organisation (WTO) efforts aimed at removing tariff and non-tariff barriers to trade and creating a neutral platform that promotes the trade of quality goods and services across nations and economic blocs.\r\n\r\nIn addition to opening up global trade opportunities, standardization also ensures that imported and locally manufactured goods are safe for human and animal life and do not harm the environment.','2026-03-29 11:49:52');
REPLACE INTO `page_content` VALUES (12,'about_val_transparency',NULL,'We conduct our business with honesty, openness, and integrity in all standardization processes.','2026-03-29 11:49:52');
REPLACE INTO `page_content` VALUES (13,'about_val_people',NULL,'We prioritize people—building trust, collaboration, and mutually beneficial relationships with stakeholders.','2026-03-29 11:49:52');
REPLACE INTO `page_content` VALUES (14,'about_val_responsiveness',NULL,'We act promptly and effectively to meet the evolving needs of our customers, markets, and partners.','2026-03-29 11:49:52');
REPLACE INTO `page_content` VALUES (15,'about_val_innovation',NULL,'We embrace creative thinking and continuous improvement to enhance our standards and services.','2026-03-29 11:49:52');
REPLACE INTO `page_content` VALUES (16,'about_val_professionalism',NULL,'We uphold the highest standards of competence, reliability, and accountability in all our operations.','2026-03-29 11:49:52');
