REPLACE INTO `page_content` VALUES (292,'cert_path_intro',NULL,'The core business of the ESWASA Certification department is the provision of an independent, third-party conformity assessment service for systems and products, in accordance with requirements of ISO/IEC 17021 for management systems certification and ISO/IEC 17065 for product certification.','2026-05-25 06:28:15');
REPLACE INTO `page_content` VALUES (293,'cert_why_title',NULL,'Why Certify','2026-05-25 06:28:15');
REPLACE INTO `page_content` VALUES (294,'cert_why_body',NULL,'Businesses with ESWASA Certification benefit from a competitive edge, greater access to local and international trade opportunities and increased market access. They achieve organisational objectives and manage their risks.','2026-05-25 06:28:15');
REPLACE INTO `page_content` VALUES (295,'cert_focus_title',NULL,'Our Focus Areas','2026-05-25 06:28:15');
REPLACE INTO `page_content` VALUES (296,'cert_focus_body',NULL,'The department mainly focuses on Management Systems Certification, Ingelo Certification, Product Certification (ESWASA Mark), Testing Services, and Scales and Metrology Services.','2026-05-25 06:28:15');
