REPLACE INTO `page_content` VALUES (347,'prod_hero_title',NULL,'Product Certification','2026-05-25 06:28:15');
REPLACE INTO `page_content` VALUES (348,'prod_about_title',NULL,'About Product Certification','2026-05-25 06:28:15');
REPLACE INTO `page_content` VALUES (349,'prod_about_body',NULL,'ESWASA implemented the ISO 17021 and 17065 Standards on our management systems and product certification schemes in order to provide trusted certification services and assurance that products and services meet customer expectations.\n\nProduct certification demonstrates commitment to safety, quality and performance standards set at an organisational, local or international level.','2026-05-25 06:28:15');
REPLACE INTO `page_content` VALUES (350,'prod_testing_title',NULL,'Product Testing Services','2026-05-25 06:28:15');
REPLACE INTO `page_content` VALUES (351,'prod_testing_body',NULL,'ESWASA facilitates testing of various products and commodities in accredited laboratories in the areas of Chemistry, Microbiology, Textiles, Mechanical, Civil and Electrical Engineering, among others. The testing is performed to verify the quality of the product and conformity to the specified standards requirements.\n\nESWASA testing services are available to the public, the industry, and various sectors of the economy.','2026-05-25 06:28:15');
