REPLACE INTO `page_content` VALUES (375,'ingelo_hero_title',NULL,'Ingelo Certification Scheme','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (376,'ingelo_img_hero',NULL,'assets/img/bg/Ingelo.png','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (377,'ingelo_intro_image',NULL,'assets/img/quality/ingelo-certification-black.png','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (378,'ingelo_intro_image_alt',NULL,'Ingelo MSME Product Certification Mark','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (379,'ingelo_intro_title',NULL,'Eswatini Standards Authority (ESWASA) Invites MSMEs to Participate','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (380,'ingelo_intro_body',NULL,'The Eswatini Standards Authority (ESWASA) invites Micro, Small and Medium Enterprises (MSMEs) to apply for participation in the Ingelo Certification Scheme — a programme developed to support local businesses in achieving product and system certification.\n\nThis initiative is designed to empower Emaswati entrepreneurs by providing them with the tools and recognition needed to compete effectively in both local and international markets.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (381,'ingelo_section_what_title',NULL,'What is the Ingelo Certification Scheme?','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (382,'ingelo_section_what_lead',NULL,'The Ingelo Certification Scheme is a national initiative launched by the Ministry of Commerce, Industry and Trade to support local producers through:','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (383,'ingelo_section_what_item_1_title',NULL,'System and Product Certification','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (384,'ingelo_section_what_item_1_body',NULL,'Supporting cottage producers in achieving certification for both their production systems and end products.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (385,'ingelo_section_what_item_2_title',NULL,'Market Requirements Compliance','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (386,'ingelo_section_what_item_2_body',NULL,'Assisting producers of products and services in meeting market requirements on quality and safety based on established standards.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (387,'ingelo_benefits_title',NULL,'Benefits of Participation','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (388,'ingelo_benefit_1_title',NULL,'Improved Product Quality & Safety','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (389,'ingelo_benefit_1_body',NULL,'Enhance your product quality and safety through standardised processes and compliance with national and international standards.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (390,'ingelo_benefit_2_title',NULL,'Market Access & Growth','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (391,'ingelo_benefit_2_body',NULL,'Gain access to local and regional markets including AfCFTA. Many markets mandate certifications as a condition for entry, reducing trade barriers and opening global opportunities.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (392,'ingelo_benefit_3_title',NULL,'Recognition Through ESWASA Approved Mark','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (393,'ingelo_benefit_3_body',NULL,'Display the trusted ESWASA Approved mark on your products, signalling compliance and quality to consumers and business partners.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (394,'ingelo_benefit_4_title',NULL,'Technical Support','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (395,'ingelo_benefit_4_body',NULL,'Receive technical guidance throughout the certification process from ESWASA experts to help you meet all requirements successfully.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (396,'ingelo_benefit_5_title',NULL,'Customer Trust & Brand Value','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (397,'ingelo_benefit_5_body',NULL,'Certifications provide independent validation, signalling reliability and safety to customers. They strengthen brand reputation and can differentiate SMEs from uncertified competitors.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (398,'ingelo_benefit_6_title',NULL,'Risk Management & Compliance','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (399,'ingelo_benefit_6_body',NULL,'Certifications help SMEs minimise legal and regulatory risks. They serve as documented proof of compliance in case of disputes, audits or liability claims.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (400,'ingelo_benefit_7_title',NULL,'Financing & Investment Appeal','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (401,'ingelo_benefit_7_body',NULL,'Investors and lenders increasingly assess intangibles when evaluating SMEs. Certifications add credibility to business operations, boosting investor confidence and enhancing company valuation.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (402,'ingelo_benefit_8_title',NULL,'Building Long-Term Competitive Advantage','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (403,'ingelo_benefit_8_body',NULL,'Unlike machinery or stock, certifications don\'t depreciate overnight — they compound business credibility over time. When integrated into IP and brand strategy, certifications become part of the SME\'s unique intangible asset portfolio.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (404,'ingelo_who_title',NULL,'Who Can Apply?','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (405,'ingelo_who_item_1',NULL,'Emaswati (Swazi citizens) — local entrepreneurs and business owners.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (406,'ingelo_who_item_2',NULL,'Local MSMEs involved in the production of any products or offering services.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (407,'ingelo_who_item_3',NULL,'Producers willing to scale up — those who are willing to increase production to meet export quota requirements by local and regional markets, through compliance with certification requirements.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (408,'ingelo_standards_title',NULL,'Available Standards','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (409,'ingelo_standards_list',NULL,'SZNS 025: Poultry processing — Hygiene requirements\nSZNS 058: Sweet potato — Grading requirements\nSZNS 049: Maize grains — Specification\nSZNS BOS 43: Onion — Grading requirements\nSZNS 037: Organic fertiliser — Specification\nSZNS 060: Banana — Grading requirements\nSZNS KS 052: Fresh courgettes/baby marrow — Specification and grading\nSZNS 031: Cattle feeds — Specification\nSZNS 035: Peanut butter — Specification\nSZNS SANS 1199: Production of Mageu\nSZNS SANS 1679: Pasteurised Milk\nSZNS CODEX STAN 296: Jam\nSZNS CODEX STAN 306: Chilli Sauce','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (410,'ingelo_apply_title',NULL,'How to Apply','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (411,'ingelo_apply_lead',NULL,'To begin the Ingelo Certification process, please:','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (412,'ingelo_apply_step_1',NULL,'Download and complete the official application form.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (413,'ingelo_apply_step_2',NULL,'Submit via email to certification@eswasa.co.sz or in person at ESWASA offices, Matsapha.','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (414,'ingelo_apply_button_text',NULL,'Download Application Form (PDF)','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (415,'ingelo_apply_button_url',NULL,'admin/uploads/ingelo_application_form.pdf','2026-05-25 06:28:16');
REPLACE INTO `page_content` VALUES (416,'ingelo_apply_support_note',NULL,'Support available: ESWASA offers free pre-application consultations and gap-analysis workshops for MSMEs. Contact us to schedule.','2026-05-25 06:28:16');
