REPLACE INTO `page_content` VALUES (535,'std_about_title',NULL,'Standards Development','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (536,'std_sectors_title',NULL,'Industry Sectors','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (537,'std_sectors_intro',NULL,'ESWASA has developed standards across the following sectors:','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (538,'std_sector_1',NULL,'Food and Agriculture','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (539,'std_sector_2',NULL,'Building and Construction','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (540,'std_sector_3',NULL,'Information Communication Technology','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (541,'std_sector_4',NULL,'Chemicals and Textiles','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (542,'std_sector_5',NULL,'Electrical and Mechanical Engineering','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (543,'std_sector_6',NULL,'Health and Safety','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (544,'std_sector_7',NULL,'Environment','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (545,'std_sector_8',NULL,'General and Services','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (546,'std_catalogue_note',NULL,'See the full Standards Catalogue.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (547,'std_what_title',NULL,'What is a Standard?','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (548,'std_what_body',NULL,'Standards are the outcome of a consultative process involving the experience and knowledge of interested parties — key industry stakeholders, consumers and their relevant associations, academic and research institutions, government ministries and regulators — who are brought together to agree on the technical contents of a standard through consensus.\n\nThey are developed on a need basis, and the need for a new standard can be initiated by industry stakeholders, an individual, a manufacturer, or a government institution through a standards proposal.\n\nStandards are designed for voluntary use and do not impose any regulations. However, laws and regulations may reference certain standards and make compliance with them mandatory.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (549,'std_benefits_title',NULL,'Benefits of Standards','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (550,'std_benefit_1',NULL,'Increased profitability through cost reduction and increased sales.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (551,'std_benefit_2',NULL,'Ensure consumers are protected from hazards to their health and safety.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (552,'std_benefit_3',NULL,'Inspire trust and consumer confidence in your business.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (553,'std_benefit_4',NULL,'Assist businesses in meeting regulatory requirements and provide access to national and international markets.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (554,'std_benefit_5',NULL,'Create a competitive advantage by improving the quality of goods and services.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (555,'std_process_title',NULL,'Standards Development Process','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (556,'std_process_step_0_title',NULL,'Preliminary Stage','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (557,'std_process_step_0_body',NULL,'An opportunity to introduce proposals (Preliminary Work Items, or PWIs) for projects that are not yet mature enough for processing — for example, an emerging-technology standard for which no reference document yet exists.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (558,'std_process_step_1_title',NULL,'Proposal Stage','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (559,'std_process_step_1_body',NULL,'ESWASA / SAC receives — and accepts or rejects — a New Work Item Proposal (NWIP) for: a new standard, a new part of an existing standard, a revision, or an amendment.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (560,'std_process_step_2_title',NULL,'Preparatory Stage','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (561,'std_process_step_2_body',NULL,'Preparation of a Working Draft (WD), if necessary. The stage concludes when the first Committee Draft (CD) is available for submission to the full Technical Committee or Sub-Committee.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (562,'std_process_step_3_title',NULL,'Committee Stage','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (563,'std_process_step_3_body',NULL,'Comments from members are received, consensus is built and voting is requested for progression of the draft to the Enquiry stage. The cycle may repeat if the CD needs further significant development.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (564,'std_process_step_4_title',NULL,'Enquiry Stage','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (565,'std_process_step_4_body',NULL,'Comments are sought from individuals or organisations not participating directly in the ESWASA committee — i.e. from the wider public. Availability of the text for enquiry is notified to the appropriate authorities. Public review allows stakeholders and the public to review draft standards and submit comments before approval, ensuring transparency, inclusiveness, consensus, and national relevance.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (566,'std_process_step_5_title',NULL,'Disposal of Comments Stage','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (567,'std_process_step_5_body',NULL,'Within 30 days of the end of the voting period, the Committee Secretariat prepares a report indicating comments received and the response on each. Every attempt is made to resolve negative votes.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (568,'std_process_step_5_pill',NULL,'within 30 days','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (569,'std_process_step_6_title',NULL,'Approval Stage','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (570,'std_process_step_6_body',NULL,'The ESWASA Standards Approvals Committee (SAC) reviews the Final Draft Standard (FDS) on technical grounds and determines whether it may advance to publication.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (571,'std_process_step_7_title',NULL,'Endorsement Stage','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (572,'std_process_step_7_body',NULL,'Final approval as an Eswatini National Standard rests with the ESWASA Council. The availability of the approved standard is notified in the Government Gazette.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (573,'std_process_step_7_pill',NULL,'≤ 30 days','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (574,'std_process_step_8_title',NULL,'Publication Stage','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (575,'std_process_step_8_body',NULL,'Once endorsed by the ESWASA Council, the text is ready for publication as a published Eswatini National Standard (SZNS).','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (576,'std_process_step_8_pill',NULL,'≤ 60 days','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (577,'std_proposal_title',NULL,'Submitting a Standards Proposal','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (578,'std_proposal_portal_url',NULL,'https://tc.eswasa.co.sz/proposal.php','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (579,'std_proposal_email_primary',NULL,'standards@eswasa.co.sz','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (580,'std_proposal_email_secondary',NULL,'info@eswasa.co.sz','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (581,'std_proposal_form_url',NULL,'','2026-05-25 08:15:07');
REPLACE INTO `page_content` VALUES (582,'std_proposal_form_label',NULL,'Download Proposal Form (PDF)','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (583,'std_proposal_note',NULL,'Note: Proposals should include the title and scope of the standard, socio-economic impacts, intended uses, and justification. Priority is given to standards supporting national priorities (e.g. food security, infrastructure, MSME competitiveness, emerging technologies).','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (584,'std_tc_section_title',NULL,'Technical Committees & Work Programmes','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (585,'std_tc_about_title',NULL,'About Technical Committees (TCs)','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (586,'std_tc_about_body',NULL,'Technical Committees (TCs) are the cornerstone of the ESWASA standards development process. They are composed of volunteers who are qualified in the subject matter and represent a balance of interested parties — including producers, users, consumers, government, and other relevant stakeholders.\n\nTCs are responsible for developing, maintaining, and revising Eswatini National Standards (SZNS) within their specific technical areas. They ensure that standards are developed through a consensus-based process, reflecting the needs and expertise of all relevant parties.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (587,'std_tc_benefits_title',NULL,'Key Benefits of Joining an ESWASA TC','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (588,'std_tc_benefit_1_title',NULL,'Market Expansion','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (589,'std_tc_benefit_1_body',NULL,'Contribute to standards that facilitate trade and regional integration. Participation ensures your products and services meet international benchmarks, opening doors to new domestic and global markets.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (590,'std_tc_benefit_2_title',NULL,'Operational Optimisation','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (591,'std_tc_benefit_2_body',NULL,'Gain early access to best practices in Quality & Management Systems (e.g. ISO 9001, ISO 45001). Implement efficient, safety-focused processes before they become mandatory — reducing waste and costs.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (592,'std_tc_benefit_3_title',NULL,'Customer Trust Building','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (593,'std_tc_benefit_3_body',NULL,'Shape standards for critical areas like Food Safety and Product Quality. Demonstrating commitment to Eswatini National Standards (SZNS) strengthens brand reputation and consumer confidence.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (594,'std_tc_benefit_4_title',NULL,'Regulatory Compliance','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (595,'std_tc_benefit_4_body',NULL,'Influence the technical requirements that may become government regulations. By contributing, you ensure standards are practical and achievable for your sector, easing future compliance burdens.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (596,'std_tc_apply_title',NULL,'Apply to be a TC Member','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (597,'std_tc_apply_body',NULL,'Becoming a member of an ESWASA Technical Committee is a great way to contribute to the development of standards that impact your industry and society. Members gain valuable insights, network with experts, and help shape the future of their technical field.\n\nEligibility: Membership is open to Eswatini citizens with relevant expertise and a commitment to the standards development process.\n\nSubmit completed applications to info@eswasa.co.sz or standards@eswasa.co.sz.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (598,'std_tc_portal_url',NULL,'https://tc.eswasa.co.sz/','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (599,'std_tc_register_url',NULL,'tcp.php','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (600,'std_workprog_title',NULL,'ESWASA Work Programmes','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (601,'std_workprog_body',NULL,'The ESWASA Work Programme details all current and scheduled standards development and revision projects. The programme is derived from national needs assessments and stakeholder requests, ensuring the standards developed align with Eswatini\'s economic and regulatory priorities. Interested stakeholders are invited to review the programme and provide feedback.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (602,'std_workprog_url',NULL,'https://tc.eswasa.co.sz/work-programme.php','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (603,'std_purchase_section_title',NULL,'Purchase Standards','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (604,'std_sales_title',NULL,'Standards Sales','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (605,'std_sales_body',NULL,'Purchase your SZNS Standards through the ESWASA office or conveniently online via the ESWASA estore.\n\nESWASA sells SZNS as well as related documents and specifications. Our services extend to sourcing other international and regional standards for you, such as ISO, IEC, ARSO, SADCSTAN, SANS and ASTM.','2026-05-25 06:28:17');
