REPLACE INTO `page_content` VALUES (629,'std_copyright_body',NULL,'Standards and publications are copyright-protected. Reproduction, copying, scanning, distribution, or unauthorised sharing without written permission from ESWASA is prohibited.\n\nCopyright protection preserves the integrity and authenticity of standards and protects intellectual property rights.','2026-05-25 06:28:17');
