REPLACE INTO `page_content` VALUES (658,'std_info_about_intro',NULL,'The Information Unit holds the database of:','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (659,'std_info_item_1',NULL,'Information on technical specifications to manufacturers and traders.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (660,'std_info_item_2',NULL,'Information relating to national, regional and international standards.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (661,'std_info_item_3',NULL,'Information to exporters and importers on the technical regulations and requirements of importing and exporting countries.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (662,'std_info_item_4',NULL,'Information on ESWASA Certified Products and Services.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (663,'std_info_about_outro',NULL,'Students, researchers, industry professionals and the general public are welcome to make use of our centre.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (664,'std_afcfta_title',NULL,'AfCFTA Annex 6 — Technical Barriers to Trade','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (665,'std_afcfta_body',NULL,'The African Continental Free Trade Area (AfCFTA) Annex 6 on Technical Barriers to Trade facilitates trade through cooperation in the areas of standards, technical regulations, conformity assessment, accreditation and metrology.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (666,'std_nep_title',NULL,'National Enquiry Point (WTO/TBT)','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (667,'std_nep_body',NULL,'ESWASA serves as the National Enquiry Point (NEP) for Technical Barriers to Trade (WTO/TBT) information. ESWASA receives notifications on technical regulations from the WTO and disseminates them to stakeholders.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (668,'std_nep_image',NULL,'assets/img/WTO.png','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (669,'std_nep_image_alt',NULL,'World Trade Organization — Technical Barriers to Trade','2026-05-25 06:28:17');
