REPLACE INTO `page_content` VALUES (678,'tcp_hero_title',NULL,'Technical Committee Platform','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (679,'tcp_intro_title',NULL,'About Technical Committees (TCs)','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (680,'tcp_intro_body',NULL,'Technical Committees (TCs) are the cornerstone of the ESWASA standards development process. They are composed of volunteers who are qualified in the subject matter and represent a balance of interested parties, including producers, users, consumers, government, and other relevant stakeholders.\n\nTCs are responsible for developing, maintaining, and revising Eswatini National Standards (SZNS) within their specific technical areas. They ensure that standards are developed through a consensus-based process, reflecting the needs and expertise of all relevant parties.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (681,'tcp_benefits_title',NULL,'Key Benefits of Joining an ESWASA TC','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (682,'tcp_benefit_1_title',NULL,'Market Expansion','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (683,'tcp_benefit_1_body',NULL,'Contribute to standards that facilitate trade and regional integration. Participation ensures your products and services meet international benchmarks, opening doors to new domestic and global markets.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (684,'tcp_benefit_2_title',NULL,'Operational Optimization','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (685,'tcp_benefit_2_body',NULL,'Gain early access to best practices in Quality & Management Systems (e.g., ISO 9001, ISO 45001). Implement efficient, safety-focused processes before they become mandatory, reducing waste and costs.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (686,'tcp_benefit_3_title',NULL,'Customer Trust Building','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (687,'tcp_benefit_3_body',NULL,'Shape standards for critical areas like Food Safety and Product Quality. Demonstrating commitment to Eswatini National Standards (SZNS) strengthens brand reputation and consumer confidence.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (688,'tcp_benefit_4_title',NULL,'Regulatory Compliance','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (689,'tcp_benefit_4_body',NULL,'Influence the technical requirements that may become government regulations. By contributing, you ensure standards are practical and achievable for your sector, easing future compliance burdens.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (690,'tcp_apply_title',NULL,'Apply to be a TC Member','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (691,'tcp_apply_body',NULL,'Becoming a member of an ESWASA Technical Committee is a great way to contribute to the development of standards that impact your industry and society. Members gain valuable insights, network with experts, and help shape the future of their technical field.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (692,'tcp_apply_eligibility',NULL,'Eligibility: Membership is open to individuals with relevant expertise and a commitment to the standards development process.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (693,'tcp_apply_button_text',NULL,'Download TC Membership Application (PDF)','2026-05-25 06:28:17');
