REPLACE INTO `page_content` VALUES (707,'work_intro_body',NULL,'The **ESWASA Work Programme** details all current and scheduled standards development and revision projects. This programme is derived from national needs assessments and stakeholder requests, ensuring that the standards developed align with Eswatini\'s economic and regulatory priorities.\n\nInterested stakeholders are invited to review the programme and provide feedback. For more information on specific projects, please contact us directly.','2026-05-25 06:28:17');
