REPLACE INTO `page_content` VALUES (765,'train_about_intro_body',NULL,'We understand the unique needs of each business, which is why we offer tailor-made training solutions to industry, individuals, government agencies and other institutions in Management Systems, allowing organisations to choose a convenient location or host the training at our training centre in Matsapha.\n\nAt ESWASA Training Academy, we are proud to work with facilitators who are industry experts in various fields, Lead Auditors, and major contributors to the development of Eswatini National Standards (SZNS).','2026-05-25 06:28:17');
