REPLACE INTO `page_content` VALUES (846,'train_about_policy_application_title',NULL,'Application','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (847,'train_about_policy_application_body',NULL,'Application forms and course-related information can be accessed through this website under Training, or requested from the Training Unit — call 7602 7306 or email info@eswasa.co.sz / training@eswasa.co.sz. Applications should reach ESWASA at least 10 working days before the course commencement date. If the number of paid applicants has not reached the minimum required for a class (5 delegates), ESWASA reserves the right to postpone the course but undertakes to inform participants promptly of such developments.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (848,'train_about_policy_acceptance_tab',NULL,'Acceptance','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (849,'train_about_policy_acceptance_title',NULL,'Acceptance','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (850,'train_about_policy_acceptance_body',NULL,'Applicants will be notified of the outcome of their applications soon thereafter. Acceptance of the offer has to be acknowledged by the participant in writing and sent by email or fax to the office as soon as possible or 7 days before the start of the training for registration.','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (851,'train_about_policy_cancellations_tab',NULL,'Cancellations','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (852,'train_about_policy_cancellations_title',NULL,'Cancellations','2026-05-25 06:28:17');
REPLACE INTO `page_content` VALUES (853,'train_about_policy_cancellations_body',NULL,'A cancellation fee of 50% of the course fee will be deducted from participants who cancel after registration / confirmation or on the date of commencement of the training course. ESWASA reserves the right to postpone any course (typically due to insufficient enrolment — see Application for class minimums) and undertakes to inform participants promptly of such developments.','2026-05-25 06:28:17');
