REPLACE INTO `page_content` VALUES (954,'cal_breadcrumb_title',NULL,'Scales & Metrology Services','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (955,'cal_about_title',NULL,'About Us','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (956,'cal_about_body',NULL,'We understand the importance of accurate and reliable measurements for your business. That is why we strive to provide the best calibration services available.\n\nOur team of highly skilled technicians provide you with exceptional scale sales, service, repairs, installations, and calibration of all weighing equipment, weighbridges, and metrology equipment.\n\nWe utilise only the finest industry-standard equipment and procedures to ensure that all your measuring and testing instruments consistently function at their best, remaining accurate and reliable.','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (957,'cal_services_title',NULL,'Our Products and Services Include:','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (958,'cal_services_1_label',NULL,'Scale Sales','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (959,'cal_services_1_desc',NULL,'Supplying high-quality scales, hoppers, and weighbridges for any application.','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (960,'cal_services_2_label',NULL,'Servicing and Repairs','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (961,'cal_services_2_desc',NULL,'Expert maintenance and repair for scales, hoppers, and weighbridges to extend their lifespan and ensure performance.','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (962,'cal_services_3_label',NULL,'In-house and On-site Calibration','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (963,'cal_services_3_desc',NULL,'Comprehensive calibration services for all types of weighing, temperature, and pressure instruments, performed at our Matsapha laboratory or at your premises.','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (964,'cal_services_4_label',NULL,'Preventative Maintenance Programmes','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (965,'cal_services_4_desc',NULL,'Scheduled maintenance to prevent failures and ensure continuous accuracy.','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (966,'cal_services_5_label',NULL,'Installation','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (967,'cal_services_5_desc',NULL,'Professional installation of scales, hoppers, and weighbridges to guarantee optimal setup and performance from day one.','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (968,'cal_whatis_title',NULL,'What is Calibration?','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (969,'cal_whatis_body',NULL,'Calibration is the process of checking, by comparison with a standard, the accuracy of measuring instruments of any type, such as a pressure gauge or an industrial thermometer. It may also include adjustments to the instrument to match the standard.\n\nCalibration of your temperature and pressure instruments has two objectives. It checks the accuracy of the instrument, and it determines the traceability of the measurement. In practice, calibration may also include repair of the device if it is out of calibration. A report is provided by the calibration technician, which shows the error in measurements with the measuring device before and after the calibration.','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (970,'cal_purpose_title',NULL,'Purpose of Calibration','2026-05-25 06:28:18');
