REPLACE INTO `page_content` VALUES (1113,'services_info_1_title',NULL,'Information Centre / WTO Enquiry Point','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (1114,'services_info_1_body',NULL,'The ESWASA National Enquiry Point holds the collection of national, regional and international standards. We welcome students, researchers, industry professionals and the general public to make use of our centre. The enquiry point is a channel for mitigating problems businesses face in obtaining information on standards, technical regulations and conformity assessment procedures for the access of their products in international markets, thus eliminating technical barriers to trade.','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (1115,'services_info_2_title',NULL,'The National Enquiry Point','2026-05-25 06:28:18');
REPLACE INTO `page_content` VALUES (1116,'services_info_2_body',NULL,'The World Trade Organization (WTO) Agreement on Technical Barriers to Trade (the TBT Agreement) requires WTO members to establish a National Enquiry Point (NEP) as a way of mitigating problems business enterprises face in obtaining information on technical regulations, standards and conformity assessment procedures applicable to their products in international markets. The Eswatini Standards Authority (ESWASA) is the TBT National Enquiry Point for Eswatini.','2026-05-25 06:28:18');
