-- ESWASA migration 2026-05-25
-- Run on production DB to bring it to parity with the new code.
-- Safe to re-run: uses IF NOT EXISTS / REPLACE INTO.

-- ── 1. NEW TABLE: eswasa_quote_requests ────────────────────────
CREATE TABLE IF NOT EXISTS eswasa_quote_requests (
    id INT AUTO_INCREMENT PRIMARY KEY,
    source ENUM('training','certification','calibration','other') NOT NULL DEFAULT 'other',
    contact_name VARCHAR(255) DEFAULT NULL,
    contact_email VARCHAR(255) DEFAULT NULL,
    contact_phone VARCHAR(50) DEFAULT NULL,
    organization VARCHAR(255) DEFAULT NULL,
    raw_form LONGTEXT DEFAULT NULL,
    attachments TEXT DEFAULT NULL,
    status ENUM('new','in_progress','closed') NOT NULL DEFAULT 'new',
    notes TEXT DEFAULT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_source (source),
    INDEX idx_status (status),
    INDEX idx_created (created_at)
);

-- ── 1b. ENSURE team / board tables exist (safety net) ─────────
CREATE TABLE IF NOT EXISTS eswasa_team_members (
    id INT NOT NULL AUTO_INCREMENT,
    name VARCHAR(255) NOT NULL,
    role VARCHAR(255) NOT NULL,
    photo VARCHAR(255) DEFAULT NULL,
    bio TEXT,
    section ENUM('management','staff') NOT NULL DEFAULT 'management',
    social_linkedin VARCHAR(500) DEFAULT NULL,
    sort_order INT NOT NULL DEFAULT 0,
    is_vacant TINYINT(1) NOT NULL DEFAULT 0,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS eswasa_board_members (
    id INT NOT NULL AUTO_INCREMENT,
    name VARCHAR(255) NOT NULL,
    role VARCHAR(255) NOT NULL,
    photo VARCHAR(255) DEFAULT NULL,
    bio TEXT,
    social_linkedin VARCHAR(500) DEFAULT NULL,
    sort_order INT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- If an older eswasa_team_members exists without is_vacant, add it.
SET @col_exists := (
    SELECT COUNT(*) FROM information_schema.columns
    WHERE table_schema = DATABASE() AND table_name = 'eswasa_team_members' AND column_name = 'is_vacant'
);
SET @ddl := IF(@col_exists = 0,
    'ALTER TABLE eswasa_team_members ADD COLUMN is_vacant TINYINT(1) NOT NULL DEFAULT 0',
    'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- ── 1c. Extend team.section enum to include 'council' and migrate
--       any rows from eswasa_board_members into team as section='council'.
--       board.php has been retired; Council + Executive Team now both
--       live on Meetourteam.php and are driven by eswasa_team_members.
ALTER TABLE eswasa_team_members
  MODIFY COLUMN section ENUM('management','staff','council') NOT NULL DEFAULT 'management';

-- 1c-1. Normalize honorifics (add the period after Mr / Mrs / Ms / Dr / Prof).
--       Done BEFORE the migration so the NOT EXISTS dedupe step matches
--       correctly between board and team rows. Idempotent.
UPDATE eswasa_board_members SET name = REPLACE(name, 'Mr ',   'Mr. ')   WHERE name LIKE 'Mr %'   AND name NOT LIKE 'Mr. %';
UPDATE eswasa_board_members SET name = REPLACE(name, 'Mrs ',  'Mrs. ')  WHERE name LIKE 'Mrs %'  AND name NOT LIKE 'Mrs. %';
UPDATE eswasa_board_members SET name = REPLACE(name, 'Ms ',   'Ms. ')   WHERE name LIKE 'Ms %'   AND name NOT LIKE 'Ms. %';
UPDATE eswasa_board_members SET name = REPLACE(name, 'Dr ',   'Dr. ')   WHERE name LIKE 'Dr %'   AND name NOT LIKE 'Dr. %';
UPDATE eswasa_board_members SET name = REPLACE(name, 'Prof ', 'Prof. ') WHERE name LIKE 'Prof %' AND name NOT LIKE 'Prof. %';

UPDATE eswasa_team_members  SET name = REPLACE(name, 'Mr ',   'Mr. ')   WHERE name LIKE 'Mr %'   AND name NOT LIKE 'Mr. %';
UPDATE eswasa_team_members  SET name = REPLACE(name, 'Mrs ',  'Mrs. ')  WHERE name LIKE 'Mrs %'  AND name NOT LIKE 'Mrs. %';
UPDATE eswasa_team_members  SET name = REPLACE(name, 'Ms ',   'Ms. ')   WHERE name LIKE 'Ms %'   AND name NOT LIKE 'Ms. %';
UPDATE eswasa_team_members  SET name = REPLACE(name, 'Dr ',   'Dr. ')   WHERE name LIKE 'Dr %'   AND name NOT LIKE 'Dr. %';
UPDATE eswasa_team_members  SET name = REPLACE(name, 'Prof ', 'Prof. ') WHERE name LIKE 'Prof %' AND name NOT LIKE 'Prof. %';

  SELECT b.name, b.role, b.photo, b.bio, 'council', b.social_linkedin, b.sort_order
  FROM eswasa_board_members b
  WHERE NOT EXISTS (
    SELECT 1 FROM eswasa_team_members t WHERE t.name = b.name AND t.section = 'council'
  );

-- ── 2. CLEAN OUT KEYS THAT WERE DROPPED THIS SESSION ──────────
DELETE FROM page_content WHERE page_key LIKE 'news\_%';
DELETE FROM page_content WHERE page_key = 'breadcrumb_bg_news';
DELETE FROM page_content WHERE page_key = 'implementation_info';
DELETE FROM page_content WHERE page_key LIKE 'board\_%';
DELETE FROM page_content WHERE page_key = 'breadcrumb_bg_board';

-- Drop the 3 pre-session standards stubs that contained HTML markup
-- (e.g. "<p>Under Section 5 of the <em>Standards Act, 1968...</em></p>").
-- Standards.php has proper full-text defaults in pc_get_many() — deleting
-- these rows lets the defaults take effect; admin can edit them to
-- whatever they want from the editor and the rows will be re-created.
DELETE FROM page_content
WHERE page_key IN ('standards_mandate','standards_process_desc','standards_proposal');

